37	/// device argmax over the step's `batch` rows (read from the attend plan —
38	/// the single source of truth for the step's row count). Shared verbatim by
39	/// every batch bucket; only the plan, scratch, block table, and
40	/// `global_tokens` differ per shape.
41	#[allow(clippy::too_many_arguments)]
42	pub(super) fn run_step_body(
43	    ctx: &DeviceContext,
44	    aux: &DeviceContext,
45	    mut ep8: Option<&mut Glm52MoeEpState>,
46	    mut tp: Option<&mut Glm52MoeTpRank>,
