63	        layers.len(),
64	        caches.len()
65	    );
66	    if let Some(rank) = tp.as_ref()
67	        && !rank.slices.is_empty()
68	    {
69	        anyhow::bail!("GLM5.2 TP4 is prefill-only; decode whole-step path (LL MoE/AR) was removed");
70	    }
71	    glm52_embed_into(ctx, embed, token_ids, &mut s.hidden)?;
72	    // Layer 0's input norm is standalone (the embedding is the residual);
73	    // every later layer's input norm is fused into the previous layer's
74	    // closing add (`glm52_layer_finish_fused`).
75	    rms_norm_rows_into(
76	        ctx,
77	        s.hidden.data(),
78	        &layers[0].input_ln,
79	        GLM52_RMS_EPS,
80	        GLM52_HIDDEN,
81	        batch,
82	        s.layer.normed.data_mut(),
83	    )?;
84	    let mut carry_ready = false;
85	    for (layer, weights) in layers.iter().enumerate() {
86	        let parity = layer % 2;
87	        // Attention-TP: a head-sharded layer's o_proj partial crosses the
88	        // NCCL all-reduce inside the attention half.
89	        let tp_ar = if weights.mla.heads == crate::config::GLM52_HEADS {
90	            None
91	        } else {
92	            let rank = tp
93	                .as_deref_mut()
94	                .context("GLM5.2 sharded attention without TP state")?;
95	            Some(&mut rank.state)
96	        };
97	        glm52_layer_attention_half(
98	            ctx,
99	            Some(aux),
100	            weights,
101	            slab,
102	            caches[layer],
103	            step,
104	            s,
105	            &mut carry_ready,
106	            parity,
107	            layer == 0,
108	            tp_ar,
109	        )
110	        .with_context(|| format!("GLM5.2 layer {layer} attention half"))?;
111	        let tp_padded_mlp = false;
112	        match &weights.mlp {
113	            Glm52LayerMlp::Dense(dense) => glm52_dense_mlp_forward_into(
114	                ctx,
115	                dense,
116	                s.layer.normed2.data(),
117	                &mut s.dense_mlp,
118	                s.layer.mlp_out.data_mut(),
119	            )?,
120	            Glm52LayerMlp::MoeEp8(moe) => {
121	                let ep8 = ep8
122	                    .as_deref_mut()
123	                    .context("GLM5.2 EP MoE layer reached without DeepEP state")?;
124	                glm52_moe_ep_layer(ctx, aux, ep8, moe, s, batch, global_tokens)
125	                    .with_context(|| format!("GLM5.2 layer {layer} EP MoE"))?;
126	            }
127	            Glm52LayerMlp::MoeTp(_) => {
128	                anyhow::bail!("GLM5.2 TP4 is prefill-only; decode MoE TP path was removed");
129	            }
130	        }
131	        if layer + 1 < layers.len() {
132	            glm52_layer_finish_fused(ctx, s, parity, &layers[layer + 1].input_ln, tp_padded_mlp)?;
133	        } else {
134	            glm52_layer_finish(ctx, s, parity, tp_padded_mlp)?;
135	        }
136	        // DSpark aux-hidden capture: after layer L's closing add the residual
137	        // stream lives in `attn[parity]` (updated in place by the fused
138	        // add+norm; none of the capture layers is the last layer, which lands
139	        // in `s.hidden` instead). Recorded into the step graph — pointer-
140	        // stable, ~60 KB/row per step — only when the drafter was requested
141	        // at launch (otherwise neither the buffer nor the copy nodes exist).
142	        if let (Some(feature), Some(captured)) = (
143	            crate::dspark::GLM52_DSPARK_AUX_LAYERS
144	                .iter()
145	                .position(|&aux| aux == layer),
146	            s.captured.as_mut(),
147	        ) {
148	            copy_hidden_rows_raw_into(
149	                ctx,
150	                s.layer.attn[parity].data(),
151	                GLM52_HIDDEN,
152	                captured.data_mut(),
153	                crate::dspark::GLM52_DSPARK_CONTEXT_DIM,
154	                feature * GLM52_HIDDEN,
155	                batch,
156	            )?;
157	        }
158	    }
159	
160	    glm52_final_norm_into(ctx, &s.hidden, final_norm, &mut s.final_normed)?;
161	    glm52_lm_head_into(ctx, &s.final_normed, lm_head, &mut s.logits)?;
162	    // Device greedy argmax per row (same semantics as a host scan: lowest
163	    // index wins ties, NaN never wins) — the step's egress shrinks from the
164	    // full vocab rows to 6 bytes per row, and the kernel chain ends on-device
165	    // (the graph boundary). Two-stage: per-4096-tile partials in parallel,
166	    // then one finalize block per row — bit-identical to the single-block
167	    // scan (the partials carry global indices, same total order), and each
168	    // row's result is independent of its slot-mates.
169	    argmax_bf16_split_into(
170	        ctx,
171	        s.logits.data(),
172	        batch,
173	        lm_head.rows,
174	        &mut s.argmax_partial_values,
175	        &mut s.argmax_partial_indices,
176	        &mut s.argmax_values,
177	        &mut s.argmax_indices,
178	    )?;
179	
180	    if tp.is_some() {
181	        anyhow::bail!("GLM5.2 TP4 is prefill-only; decode vocab-parallel LL allreduce was removed");
182	    }
183	    ensure!(
184	        lm_head.rows == GLM52_VOCAB && vocab_start == 0,
185	        "GLM5.2 non-TP decode received a sharded vocabulary head"
186	    );
187	    Ok(())
188	}
189	
190	/// One layer's EP MoE half (EP8 or EP4 — the state carries the chain):
191	/// shared expert forked to the aux stream, routed path through router +
192	/// DeepEP dispatch/expert-GEMM/combine, joined by the closing add into
193	/// `mlp_out`. The events recorded here during capture become graph edges;
194	/// replay keeps the parallel branches.
195	pub(super) fn glm52_moe_ep_layer(
196	    ctx: &DeviceContext,
197	    aux: &DeviceContext,
198	    ep8: &mut Glm52MoeEpState,
199	    moe: &Glm52MoeEp8LayerWeights,
200	    s: &mut Glm52DecodeScratch,
201	    batch: usize,
202	    global_tokens: usize,
203	) -> Result<()> {
204	    // Fork: the shared expert only needs `normed2`, so it runs on the aux
205	    // stream concurrently with the routed path's dispatch/grouped-GEMM/
206	    // combine — the cooperative collectives occupy a fixed SM slice and
207	    // mostly wait on peers, leaving the rest of the GPU free.
208	    let normed_ready = ctx.stream.record_event(None)?;
209	    aux.stream.wait(&normed_ready)?;
210	    moe.shared.forward_into(
211	        aux,
212	        s.layer.normed2.data(),
213	        &mut s.shared_mlp,
214	        s.layer.shared_out.data_mut(),
215	    )?;
216	    let shared_done = aux.stream.record_event(None)?;
217	
218	    run_ep_router_into(ctx, &moe.router, s.layer.normed2.data(), &mut s.router)?;
219	    let dispatched = ep8.routed_forward(
220	        ctx,
221	        &moe.bank,
222	        Some((s.layer.normed2.data(), &s.router.route, batch)),
223	        global_tokens,
224	    )?;
225	    ensure!(
226	        dispatched,
227	        "EP MoE returned no combined output for the dispatched rows"
228	    );
229	    // Join: the closing add consumes both branches.
230	    ctx.stream.wait(&shared_done)?;
231	    add_scaled_bf16_into(
232	        ctx,
233	        ep8.combined(),
234	        crate::config::GLM52_ROUTED_SCALING_FACTOR as f32,
235	        s.layer.shared_out.data(),
236	        batch * GLM52_HIDDEN,
237	        s.layer.mlp_out.data_mut(),
238	    )
239	}
