150	fn seeded_hidden(seed: u64, count: usize) -> Vec<bf16> {
151	    (0..count)
152	        .map(|i| {
153	            let mut z = seed.wrapping_add((i as u64 + 1).wrapping_mul(0x9E37_79B9_7F4A_7C15));
154	            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
155	            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
156	            z ^= z >> 31;
157	            let u = (z >> 11) as f64 / (1u64 << 53) as f64;
158	            bf16::from_f32(((u - 0.5) * 4.0) as f32)
159	        })
160	        .collect()
161	}
