163	/// Mirror of the harness `seeded_token_ids`: splitmix64 uniform on `seed ^
164	/// 0xB00C`, scaled to the vocab (f64 multiply + truncation, exact both sides).
165	fn seeded_token_ids(seed: u64, count: usize, vocab: usize) -> Vec<u32> {
166	    let seed = seed ^ 0xB00C;
167	    (0..count)
168	        .map(|i| {
169	            let mut z = seed.wrapping_add((i as u64 + 1).wrapping_mul(0x9E37_79B9_7F4A_7C15));
170	            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
171	            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
172	            z ^= z >> 31;
173	            let u = (z >> 11) as f64 / (1u64 << 53) as f64;
174	            ((u * vocab as f64) as u64).min(vocab as u64 - 1) as u32
175	        })
176	        .collect()
177	}
178	
179	fn bf16_digest(data: &[bf16]) -> String {
180	    let mut hasher = Sha256::new();
181	    for v in data {
182	        hasher.update(v.to_bits().to_le_bytes());
183	    }
184	    hex::encode(&hasher.finalize()[..8])
185	}
