187	/// Load one whole bf16 tensor from the checkpoint by name.
188	fn load_bf16(model_path: &Path, name: &str) -> Result<Vec<u8>> {
189	    let index: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(
190	        model_path.join("model.safetensors.index.json"),
191	    )?)?;
192	    let shard = index["weight_map"][name]
193	        .as_str()
194	        .with_context(|| format!("{name} missing from weight map"))?;
195	    let mmap = crate::weights::mmap_file(&model_path.join(shard))?;
196	    let st = safetensors::SafeTensors::deserialize(mmap.as_ref())?;
197	    Ok(st.tensor(name)?.data().to_vec())
198	}
