200	#[test]
201	#[ignore = "requires GPU + GLM-5.2-FP8 checkpoint"]
202	fn bookend_oracle_gate() -> Result<()> {
203	    assert!(
204	        !ORACLE_LOGITS_PROBES.is_empty(),
205	        "probe block is the ungenerated placeholder — run the harness and paste"
206	    );
207	    let model_path = std::env::var_os("PEGAINFER_TEST_MODEL_PATH")
208	        .map_or_else(|| PathBuf::from("models/GLM-5.2-FP8"), PathBuf::from);
209	
210	    let hidden_host = seeded_hidden(ORACLE_SEED, ORACLE_CTX * GLM52_HIDDEN);
211	    let digest = bf16_digest(&hidden_host);
212	    ensure!(
213	        digest == ORACLE_HIDDEN_DIGEST,
214	        "input digest {digest} != oracle {ORACLE_HIDDEN_DIGEST}: PRNG drift or stale probes"
215	    );
216	    let token_ids = seeded_token_ids(ORACLE_SEED, ORACLE_CTX, GLM52_VOCAB);
217	
218	    let ctx = DeviceContext::new()?;
219	    let embed = DeviceMatrix::from_safetensors(
220	        &ctx,
221	        &load_bf16(&model_path, "model.embed_tokens.weight")?,
222	        GLM52_VOCAB,
223	        GLM52_HIDDEN,
224	    )?;
225	    let norm_weight =
226	        DeviceVec::from_safetensors(&ctx, &load_bf16(&model_path, "model.norm.weight")?)?;
227	    let lm_head = DeviceMatrix::from_safetensors(
228	        &ctx,
229	        &load_bf16(&model_path, "lm_head.weight")?,
230	        GLM52_VOCAB,
231	        GLM52_HIDDEN,
232	    )?;
233	
234	    // ---- embed: exact gather digest ----
235	    let mut token_id_buf = ctx.stream.alloc_zeros::<u32>(1)?;
236	    let mut embed_rows: Vec<bf16> = Vec::with_capacity(ORACLE_CTX * GLM52_HIDDEN);
237	    for &id in &token_ids {
238	        ctx.stream.memcpy_htod(&[id], &mut token_id_buf)?;
239	        let row = glm52_embed(&ctx, &embed, &token_id_buf)?;
240	        embed_rows.extend(ctx.stream.clone_dtoh(row.data())?);
241	    }
242	    let embed_digest = bf16_digest(&embed_rows);
243	    ensure!(
244	        embed_digest == ORACLE_EMBED_ROWS_DIGEST,
245	        "embed rows digest {embed_digest} != oracle {ORACLE_EMBED_ROWS_DIGEST} (gather is exact — this is a hard bug)"
246	    );
247	    println!("bookend embed: digest exact ({ORACLE_CTX} rows)");
248	
249	    // ---- final norm + lm_head: probes + exact argmax ----
250	    ensure!(ORACLE_ARGMAX.len() == ORACLE_CTX, "argmax length mismatch");
251	    let mut logits_all: Vec<f32> = Vec::with_capacity(ORACLE_CTX * GLM52_VOCAB);
252	    for position in 0..ORACLE_CTX {
253	        let mut hidden = Rows::<GLM52_HIDDEN>::zeros(&ctx, 1)?;
254	        ctx.stream.memcpy_htod(
255	            &hidden_host[position * GLM52_HIDDEN..(position + 1) * GLM52_HIDDEN],
256	            hidden.data_mut(),
257	        )?;
258	        let normed = glm52_final_norm(&ctx, &hidden, &norm_weight)?;
259	        let logits = glm52_lm_head(&ctx, &normed, &lm_head)?;
260	        let logits_host: Vec<f32> = ctx
261	            .stream
262	            .clone_dtoh(logits.data())?
263	            .iter()
264	            .map(|v| v.to_f32())
265	            .collect();
266	        let argmax = logits_host
267	            .iter()
268	            .enumerate()
269	            .max_by(|a, b| a.1.total_cmp(b.1))
270	            .map(|(i, _)| i as u32)
271	            .unwrap();
272	        ensure!(
273	            argmax == ORACLE_ARGMAX[position],
274	            "argmax mismatch at position {position}: engine {argmax} vs oracle {}",
275	            ORACLE_ARGMAX[position]
276	        );
277	        logits_all.extend(logits_host);
278	    }
279	    println!("bookend argmax: exact across {ORACLE_CTX} positions");
280	
281	    let tol = ORACLE_LOGITS_REL_TOL * ORACLE_LOGITS_RMS;
282	    let failures: Vec<_> = ORACLE_LOGITS_PROBES
283	        .iter()
284	        .filter(|&&(idx, expected)| (logits_all[idx] - expected).abs() > tol)
285	        .collect();
286	    println!(
287	        "bookend logits: {}/{} probes within tol={tol:.6e}",
288	        ORACLE_LOGITS_PROBES.len() - failures.len(),
289	        ORACLE_LOGITS_PROBES.len()
290	    );
291	    for &&(idx, expected) in failures.iter().take(10) {
292	        println!(
293	            "  probe[{idx}]: oracle {expected:.6} vs engine {:.6}",
294	            logits_all[idx]
295	        );
296	    }
297	    ensure!(
298	        failures.is_empty(),
299	        "{} probes out of tolerance",
300	        failures.len()
301	    );
302	    Ok(())
303	}
